head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05017";
scwin.lastJob = "";  // 업무 처리명(confirmJob 이 채우고 alertJobResult 가 읽는다 — as-is 전역 LastJob)
scwin.LD_MKT_TP_CD = '1';
scwin.BZ_NEWLST = 1;
scwin.BZ_ADDPRE = 2;
scwin.BZ_ADDLST = 3;
scwin.CD_NEWLST = '003';
scwin.form = null;
scwin.w = '375';
scwin.h = '220';
scwin.instCodeWin = null;
scwin.openCodeObj = null;
scwin.openNameObj = null;
scwin.l = undefined;
scwin.t = undefined;

// as-is 공용 상수 — 셸이 js/elw.js 를 싣지 않아 화면에 선언한다(KRX 합의 대상).

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_elwKoValuPrcMethd", attr: "label", fn: function () { return String(dma_readDataVO.get("elwKoValuPrcMethd")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  ===  0); } }, { id: "btn_Register_2", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  1); } }, { id: "btn_ElwSub", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  4); } }, { id: "btn_Register_4", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  1); } }, { id: "btn_ElwSub_2", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  4); } }, { id: "btn_Register_3", fn: function(){ return ((dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  ===  0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_209", entity: "dlt_readDataVOArrayUly", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return "주권발행기관_" + String(i + 1); } }, { childId: "ipt_ulyIsuCd", fn: function (v, i) { return String(v("ulyIsuCd")); } }, { childId: "ipt_ulyIsuNm", fn: function (v, i) { return String(v("ulyIsuNm")); } }, { childId: "ipt_ulyCompstRto", fn: function (v, i) { return String(v("ulyCompstRto")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isuTotSum", fn: function () { return String((String(dma_readDataVO.get("isuShrs")) * String(dma_readDataVO.get("isuPrc")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.ElwForm || { elements: [] });
        $c.util.getComponent("dma_RegisterReq").set("bzCd", scwin.BZ_NEWLST);
        $c.util.getComponent("dma_RegisterReq").set("listBzTpCd", scwin.CD_NEWLST);
        $c.util.getComponent("dma_RegisterReq").set("spotIsuTrdMktTpCd", scwin.LD_MKT_TP_CD);
        /* 수동 전환 필요: transTbl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        /* 수동 전환 필요: transTbl[1].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        /* 수동 전환 필요: transTbl[2].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        /* 수동 전환 필요: transTbl[3].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        $c.util.getComponent('ipt_isuShtNm').setValue($c.util.getComponent("dma_RegisterReq").get("isuAbbrv1") + $c.util.getComponent("dma_RegisterReq").get("isuAbbrv2") + $c.util.getComponent("dma_RegisterReq").get("isuAbbrv3") + $c.util.getComponent("dma_RegisterReq").get("isuAbbrv4"));
        $c.util.getComponent('ipt_engIsuShtNm').setValue($c.util.getComponent("dma_RegisterReq").get("isuEngAbbrv1") + $c.util.getComponent("dma_RegisterReq").get("isuEngAbbrv2") + $c.util.getComponent("dma_RegisterReq").get("isuEngAbbrv3") + $c.util.getComponent("dma_RegisterReq").get("isuEngAbbrv4"));
        scwin.commaValueAll();
        scwin.setSelectDisabled(true);
        scwin.setElwKoValuPrcMethd();
        setElwExerContn();
        setElwKoExerContn();
        setElwKoBasPrc();
        setElwExpValuPrcMethd($c.util.getComponent('ipt_elwExpValuPrcMethd').getValue());
        setElwCompnsRt();
        setIsuExp();
        if ($c.util.getComponent('slc_fncUlyTpCd').getValue()=== 2) {
            for (let i = 0; i < $c.util.getComponent('ipt_ulyIsuCd').length; i++) {
                $c.util.getComponent(["ipt_ulyCompstRto", "ipt_ulyCompstRto_2"][i]).readOnly = false;
            }
        } else {
            if ($c.util.getComponent('slc_fncUlyTpCd').getValue()=== 3) {

            }
        }
        if ($c.util.getComponent('ipt_elwFinalPayVal') == null || $c.util.getComponent('ipt_elwFinalPayVal').getValue()=== 0) {
            $c.util.getComponent('ipt_elwFinalPayVal').setValue("");
        }
        scwin.calcIsuTotSum();
        await (async () => { const m = $c.util.getComponent("dma_readDataVO"); const v = (m && m.get) ? m.get("resultMsg") : ""; if (v) { await $c.win.alert(String(v)); } })();
        if (($c.util.getComponent('dma_RegisterReq').get('billLstSaveStatCd')) === 0) {
            if ($c.util.getComponent('slc_elwObjIdxTpCd').getValue()=== '6') {
                $c.util.getComponent('slc_idxCalcInstNm').setSelectedIndex(1);
                $c.util.getComponent('slc_trdMktNm').setSelectedIndex(1);
            } else {
                if ($c.util.getComponent('slc_elwObjIdxTpCd').getValue()=== '7') {
                    $c.util.getComponent('slc_idxCalcInstNm').setSelectedIndex(2);
                    $c.util.getComponent('slc_trdMktNm').setSelectedIndex(2);
                }
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05017.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
